function validate([word]) {
  if (typeof word !== 'string' || word.length < 1 || word.length > 15) return 'word needs 1 to 15 letters.';
  if (word.length > 14) return 'Here word can have at most 14 letters: 2^15 abbreviations exceed the output limit.';
  if (!/^[a-z]+$/.test(word)) return 'word contains only lowercase English letters.';
  return null;
}

