function generateAbbreviations(word) {
  const result = [];

  const backtrack = (index, current, count) => {
    if (index === word.length) {
      result.push(count > 0 ? current + count : current);
      return;
    }
    backtrack(index + 1, current, count + 1);
    const prefix = count > 0 ? current + count : current;
    backtrack(index + 1, prefix + word[index], 0);
  };

  backtrack(0, '', 0);
  return result;
}

