function generateAbbreviations(word) {
  // Each bit of mask says whether that letter is replaced; runs of set bits become numbers.
  const n = word.length;
  const result = [];
  for (let mask = 0; mask < (1 << n); mask++) {
    let text = '';
    let run = 0;
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) {
        run++;
      } else {
        if (run) text += String(run);
        run = 0;
        text += word[i];
      }
    }
    if (run) text += String(run);
    result.push(text);
  }
  return result;
}

