function generate(rand, size) {
  const n = size === 'large' ? 13 : 1 + Math.floor(rand() * 7);
  const letters = rand() < 0.4 ? 'ab' : 'abcdefghijklmnopqrstuvwxyz';
  let word = '';
  for (let i = 0; i < n; i++) word += letters[Math.floor(rand() * letters.length)];
  return [word];
}
